INSERT INTO "refs_fishery_config"."areas_of_operation" AS t ("code", "name_en", "name_fr", "description_en", "description_fr") OVERRIDING SYSTEM VALUE VALUES ('ABNJ', 'Areas beyond national jurisdiction', 'Zones hors juridictions nationales', 'Vessels operate exclusively in areas beyond national jurisdiction of their flag state (i.e., high seas or areas under national jurisdiction of other coastal states)', 'Les navires opèrent exclusivement dans des zones situées au-delà de la juridiction nationale de leur État du pavillon (c''est-à-dire en haute mer ou dans des zones placées sous la juridiction nationale d''autres États côtiers)') ON CONFLICT ("code") DO UPDATE SET "name_en" = EXCLUDED."name_en", "name_fr" = EXCLUDED."name_fr", "description_en" = EXCLUDED."description_en", "description_fr" = EXCLUDED."description_fr" WHERE (t."name_en", t."name_fr", t."description_en", t."description_fr") IS DISTINCT FROM (EXCLUDED."name_en", EXCLUDED."name_fr", EXCLUDED."description_en", EXCLUDED."description_fr");
INSERT INTO "refs_fishery_config"."areas_of_operation" AS t ("code", "name_en", "name_fr", "description_en", "description_fr") OVERRIDING SYSTEM VALUE VALUES ('NJA', 'National jurisdiction areas', 'Zones sous juridictions nationales', 'Vessels operate exclusively within areas under national jurisdiction of their flag state (territorial sea, contiguous zone as well as EEZ waters)', 'Les navires opèrent exclusivement dans les zones relevant de la juridiction nationale de leur État du pavillon (mer territoriale, zone contiguë et eaux de la ZEE)') ON CONFLICT ("code") DO UPDATE SET "name_en" = EXCLUDED."name_en", "name_fr" = EXCLUDED."name_fr", "description_en" = EXCLUDED."description_en", "description_fr" = EXCLUDED."description_fr" WHERE (t."name_en", t."name_fr", t."description_en", t."description_fr") IS DISTINCT FROM (EXCLUDED."name_en", EXCLUDED."name_fr", EXCLUDED."description_en", EXCLUDED."description_fr");
INSERT INTO "refs_fishery_config"."areas_of_operation" AS t ("code", "name_en", "name_fr", "description_en", "description_fr") OVERRIDING SYSTEM VALUE VALUES ('NJA_ABNJ', 'National jurisdiction areas and beyond', 'Zones sous et hors jurisdictions nationales', 'Vessels operate in areas under national jurisdiction as well as in areas beyond national jurisdiction of their flag state (i.e., high seas or areas under national jurisdiction of other coastal states)', 'Les navires opèrent dans des zones sous juridiction nationale ainsi que dans des zones situées au-delà de la juridiction nationale de l''État du pavillon (c''est-à-dire en haute mer ou dans des zones sous juridiction nationale d''autres États côtiers)') ON CONFLICT ("code") DO UPDATE SET "name_en" = EXCLUDED."name_en", "name_fr" = EXCLUDED."name_fr", "description_en" = EXCLUDED."description_en", "description_fr" = EXCLUDED."description_fr" WHERE (t."name_en", t."name_fr", t."description_en", t."description_fr") IS DISTINCT FROM (EXCLUDED."name_en", EXCLUDED."name_fr", EXCLUDED."description_en", EXCLUDED."description_fr");
INSERT INTO "refs_fishery_config"."fishery_categories" AS t ("code", "name_en", "name_fr", "description_en", "description_fr", "rav_vessels", "minimum_grid_size") OVERRIDING SYSTEM VALUE VALUES ('COASTAL', 'Coastal fisheries', 'Pêcheries côtières', 'Fisheries other than longline or surface fisheries, also called artisanal fisheries', 'Pêcheries autres que palangrières et de surface, également appelées pêcheries artisanales', '0', NULL) ON CONFLICT ("code") DO UPDATE SET "name_en" = EXCLUDED."name_en", "name_fr" = EXCLUDED."name_fr", "description_en" = EXCLUDED."description_en", "description_fr" = EXCLUDED."description_fr", "rav_vessels" = EXCLUDED."rav_vessels", "minimum_grid_size" = EXCLUDED."minimum_grid_size" WHERE (t."name_en", t."name_fr", t."description_en", t."description_fr", t."rav_vessels", t."minimum_grid_size") IS DISTINCT FROM (EXCLUDED."name_en", EXCLUDED."name_fr", EXCLUDED."description_en", EXCLUDED."description_fr", EXCLUDED."rav_vessels", EXCLUDED."minimum_grid_size");
INSERT INTO "refs_fishery_config"."fishery_categories" AS t ("code", "name_en", "name_fr", "description_en", "description_fr", "rav_vessels", "minimum_grid_size") OVERRIDING SYSTEM VALUE VALUES ('LONGLINE', 'Longline fisheries', 'Pêcheries palangrières', 'Fisheries operated by vessels in the IOTC Record of Authorized Vessels that use longline gear', 'Pêcheries opérées par des navires enregistrés dans le Registre CTOI des Navires Autorisés utilisant la palangre comme engin de pêche', '1', 'GRID05x05') ON CONFLICT ("code") DO UPDATE SET "name_en" = EXCLUDED."name_en", "name_fr" = EXCLUDED."name_fr", "description_en" = EXCLUDED."description_en", "description_fr" = EXCLUDED."description_fr", "rav_vessels" = EXCLUDED."rav_vessels", "minimum_grid_size" = EXCLUDED."minimum_grid_size" WHERE (t."name_en", t."name_fr", t."description_en", t."description_fr", t."rav_vessels", t."minimum_grid_size") IS DISTINCT FROM (EXCLUDED."name_en", EXCLUDED."name_fr", EXCLUDED."description_en", EXCLUDED."description_fr", EXCLUDED."rav_vessels", EXCLUDED."minimum_grid_size");
INSERT INTO "refs_fishery_config"."fishery_categories" AS t ("code", "name_en", "name_fr", "description_en", "description_fr", "rav_vessels", "minimum_grid_size") OVERRIDING SYSTEM VALUE VALUES ('SURFACE', 'Surface fisheries', 'Pêcheries de surface', 'All fisheries operated by vessels in the IOTC Record of Authorized Vessels other than longline fisheries; in particular purse seine, pole-and-line, gillnet fisheries, handline and trolling vessels', 'Toutes les pêcheries opérées par des navires enregistrés dans le Registre CTOI des Navires Autorisés autres que les pêcheries palangrières, utilisant notamment la senne, la canne, le filet maillant, les lignes à main ou de traîne', '1', 'GRID01x01') ON CONFLICT ("code") DO UPDATE SET "name_en" = EXCLUDED."name_en", "name_fr" = EXCLUDED."name_fr", "description_en" = EXCLUDED."description_en", "description_fr" = EXCLUDED."description_fr", "rav_vessels" = EXCLUDED."rav_vessels", "minimum_grid_size" = EXCLUDED."minimum_grid_size" WHERE (t."name_en", t."name_fr", t."description_en", t."description_fr", t."rav_vessels", t."minimum_grid_size") IS DISTINCT FROM (EXCLUDED."name_en", EXCLUDED."name_fr", EXCLUDED."description_en", EXCLUDED."description_fr", EXCLUDED."rav_vessels", EXCLUDED."minimum_grid_size");
INSERT INTO "refs_fishery_config"."fishery_purposes" AS t ("code", "name_en", "name_fr", "description_en", "description_fr") OVERRIDING SYSTEM VALUE VALUES ('COM', 'Commercial', 'Commerciale', 'Fish is caught for commercial sale or export, including supply to processing or canning facilities', 'Poisson capturé pour la vente commerciale ou l’exportation, y compris l’approvisionnement des usines de transformation ou de conserverie') ON CONFLICT ("code") DO UPDATE SET "name_en" = EXCLUDED."name_en", "name_fr" = EXCLUDED."name_fr", "description_en" = EXCLUDED."description_en", "description_fr" = EXCLUDED."description_fr" WHERE (t."name_en", t."name_fr", t."description_en", t."description_fr") IS DISTINCT FROM (EXCLUDED."name_en", EXCLUDED."name_fr", EXCLUDED."description_en", EXCLUDED."description_fr");
