INSERT INTO "refs_fishery_config"."fishing_modes" AS t ("code", "name_en", "name_fr", "description_en", "description_fr") OVERRIDING SYSTEM VALUE VALUES ('DA', 'Fishing on dolphin-associated schools', 'Sur bancs associés à des dauphins', 'Fish is caught with the fishing gear when associated with dolphins', 'Les poissons sont capturés par l''engin de pêche lorsqu''ils sont en association avec des dauphins') ON CONFLICT ("code") DO UPDATE SET "name_en" = EXCLUDED."name_en", "name_fr" = EXCLUDED."name_fr", "description_en" = EXCLUDED."description_en", "description_fr" = EXCLUDED."description_fr" WHERE (t."name_en", t."name_fr", t."description_en", t."description_fr") IS DISTINCT FROM (EXCLUDED."name_en", EXCLUDED."name_fr", EXCLUDED."description_en", EXCLUDED."description_fr");
