INSERT INTO "refs_fishery_config"."gear_groups" AS t ("code", "name_en", "name_fr", "description_en", "description_fr") OVERRIDING SYSTEM VALUE VALUES ('LL', 'Longlines', 'Palangres', 'A subset of ISSCFG 09 (hooks and lines): includes set longlines (09.31), and drifting longlines (09.32)', 'Extrait d''ISSCFG 09 (lignes et hameçons) : inclut les palangres ancrées (09.31) et les palangres dérivantes (09.32)') ON CONFLICT ("code") DO UPDATE SET "name_en" = EXCLUDED."name_en", "name_fr" = EXCLUDED."name_fr", "description_en" = EXCLUDED."description_en", "description_fr" = EXCLUDED."description_fr" WHERE (t."name_en", t."name_fr", t."description_en", t."description_fr") IS DISTINCT FROM (EXCLUDED."name_en", EXCLUDED."name_fr", EXCLUDED."description_en", EXCLUDED."description_fr");
INSERT INTO "refs_fishery_config"."gear_groups" AS t ("code", "name_en", "name_fr", "description_en", "description_fr") OVERRIDING SYSTEM VALUE VALUES ('OT', 'Other gears', 'Autres engins', 'A subset of ISSCFG 02 (seine nets), 03 (trawls), 05 (lift nets), 07 (falling gear), 08 (traps), and 10 (miscellaneous gear)', 'Extrait d''ISSCFG 02 (sennes), 03 (chaluts), 05 (filets soulevés), 07 (engins retombants), 08 (casiers) et 10 (divers engins de pêche)') ON CONFLICT ("code") DO UPDATE SET "name_en" = EXCLUDED."name_en", "name_fr" = EXCLUDED."name_fr", "description_en" = EXCLUDED."description_en", "description_fr" = EXCLUDED."description_fr" WHERE (t."name_en", t."name_fr", t."description_en", t."description_fr") IS DISTINCT FROM (EXCLUDED."name_en", EXCLUDED."name_fr", EXCLUDED."description_en", EXCLUDED."description_fr");
INSERT INTO "refs_fishery_config"."gear_groups" AS t ("code", "name_en", "name_fr", "description_en", "description_fr") OVERRIDING SYSTEM VALUE VALUES ('PL', 'Pole-and-lines', 'Cannes', 'A subset of ISSCFG 09 (hooks and lines): includes manual (09.1) and mechanized pole-and-lines (09.2)', 'Extrait d''ISSCFG 09 (lignes et hameçons) : inclut lignes avec cannes manuelles (09.1) et mécanisées (09.2)') ON CONFLICT ("code") DO UPDATE SET "name_en" = EXCLUDED."name_en", "name_fr" = EXCLUDED."name_fr", "description_en" = EXCLUDED."description_en", "description_fr" = EXCLUDED."description_fr" WHERE (t."name_en", t."name_fr", t."description_en", t."description_fr") IS DISTINCT FROM (EXCLUDED."name_en", EXCLUDED."name_fr", EXCLUDED."description_en", EXCLUDED."description_fr");
INSERT INTO "refs_fishery_config"."gear_groups" AS t ("code", "name_en", "name_fr", "description_en", "description_fr") OVERRIDING SYSTEM VALUE VALUES ('PS', 'Purse seines', 'Sennes', 'A subset of ISSCFG 01 (surrounding nets): includes purse seines (01.1) and ring nets and lampara nets, i.e. surrounding nets without purse seines (01.2)', 'Extrait d''ISSCFG 01 (filets tournants) : inclut les filets tournants avec coulisse (01.1) et les filets tournants sans coulisse (filets lampara, "ring nets") (01.2)') ON CONFLICT ("code") DO UPDATE SET "name_en" = EXCLUDED."name_en", "name_fr" = EXCLUDED."name_fr", "description_en" = EXCLUDED."description_en", "description_fr" = EXCLUDED."description_fr" WHERE (t."name_en", t."name_fr", t."description_en", t."description_fr") IS DISTINCT FROM (EXCLUDED."name_en", EXCLUDED."name_fr", EXCLUDED."description_en", EXCLUDED."description_fr");
