INSERT INTO "refs_fishery_config"."target_species" AS t ("code", "name_en", "name_fr", "description_en", "description_fr") OVERRIDING SYSTEM VALUE VALUES ('NT', 'Neritic tunas, seerfish, and tropical tunas', 'Thons néritiques, maquereaux espagnols et thons tropicaux', 'Bullet tuna (BLT), frigate tuna (FRI), longtail tuna (LOT), kawakawa (KAW), narrow-barred Spanish mackerel  (COM), Indo-Pacific king mackerel (GUT), bigeye tuna (BET), skipjack tuna (SKJ), yellowfin tuna (YFT), or any combination of these', 'Bonitou (BLT), auxide (FRI), thon mignon (LOT), thonine orientale (KAW), thazard rayé (COM), thazard ponctué Indo-Pacifique (GUT), patudo (BET), listao (SKJ), albacore (YFT) ou toute combinaison de ceux-ci') ON CONFLICT ("code") DO UPDATE SET "name_en" = EXCLUDED."name_en", "name_fr" = EXCLUDED."name_fr", "description_en" = EXCLUDED."description_en", "description_fr" = EXCLUDED."description_fr" WHERE (t."name_en", t."name_fr", t."description_en", t."description_fr") IS DISTINCT FROM (EXCLUDED."name_en", EXCLUDED."name_fr", EXCLUDED."description_en", EXCLUDED."description_fr");
